    days: 6,
    summary: '满月村的娃都是田里结的，接生婆一死摘瓜手艺断了；程实须在第六日前，为那颗没有爹妈的第八瓜找到一个喊得出口的亲名。',
    objective: '在瓜熟蒂落之前，找到那颗不肯落地的瓜',
