      '程实这一觉，是被尿憋醒的——紧接着他发现，憋醒他的不是尿，是窗外那一声接一声、根本不像婴儿能哭出来的啼哭。',
      '泥土是甜的。',
      '不是雨后那种清新的土腥，是一种发酵过的、从根须深处沤出来的甜腥，像谁家灶上煨了三天的浓汤，甜得发腻。',
      '他躺在一间农舍的土炕上，窗外是凌晨的田野。雾气贴着地皮走，田垄一畦一畦排得整整齐齐，每畦尽头都支着一人多高的木架。',
      '架上挂着瓜。',
      '圆滚滚，青白色，随着晨风轻轻晃。最远的那排架子后面，隐约有瓜荚裂开的轻响，紧跟着，一声婴儿啼哭刺破了晨雾。',
      '田埂上立刻有农人小跑过去，片刻后，襁褓里多了个哇哇直哭的娃娃。农人跪在田里，冲着东方磕了三个响头。',
      '程实趴在窗棂上，看完了全程，默默把窗户关上了。'
