// 10 面目全非（chaos_1）跳转图：
//   n1身份牌(A暗号/B暗号固定[暗号泄露]/C分头/D观察[签筒])
//   → n2规则(A牌自择/B采访/C查城志/D行骗[筒不听骗])
//   → n3通缉犯(A跑/B三教九流/C顶包/D假死 random[败→空白牌])
//   → n4排除法(B抽签人/C铁律不动) → n5抽签人(B自家人/C换签尺) → n6候选(A报签筒/B报抽签人/C观望/D思路)
//   → n7将死牌(A硬抢失败/B骗行刑队/C劫法场/D受刑[空白牌])
//   → n8提点(A答案成立/B造恒定线) → n9造恒定(A上报[答案成立]/B藏牌[签筒紊乱]) → n10反噬(A拔牌/B硬扛/C谈判[需自家人]/D双倍紊乱)
//   → n11大洗牌 autoRoute：空白牌→end_C淘汰 / 自家人+签筒紊乱→end_hidden上手(gaze) / 答案成立→end_S定桩 / 报签筒|报抽签人→end_A半对 / default→end_B五张脸
//
// 11 一问三不知（folly_1）跳转图：
//   n1漏(A漏序/B救同伴[C同伴保住]/C大忘节/D行骗[谎不漏])
//   → n2大忘(A忘即安/B查井 random[井中沉知/落水]/C老痴/D解题线)
//   → n3实验(A教算术败/B教编谎败/C无形不漏/D老痴线) → n4老痴(A酿智/B错题/C消化)
//   → n5提点(A编云/B忘忧线) → n6编云(A云船/B等检验) → n7大忘节(A扎根/B放知[需井中沉知])
//   → n8终局 autoRoute：落水→end_C淘汰 / 忘忧线→end_hidden忘忧(gaze) / 扎根→end_S云器 / 放知→end_A想起 / default→end_B礼数
//
// 12 此时无声（silence_1）跳转图：
//   n1字钱(A营生/B启齿楼/C童谣免费/D夜鸣)
//   → n2禁句(A回声兽[需夜鸣]/B粮仓旧案/C言楼主/D谷外)
