//   → n7有声(A正名/B收束/C独自咽回[按源文隐藏分支条件补入])
//   → n8终局 autoRoute：独自咽回→end_hidden哑(gaze) / 正名→end_S此时有声 / 收束→end_A一日免费 / default→end_B更哑

