    difficulty: 'B',
    days: 5,
    summary: '身份牌之城每日卯时全员换脸，程实须在尘埃落定前找到那件从没换过的东西——"每日必换"这条规矩本身。',
    objective: '在尘埃落定之前，找到那件从没换过的东西',
    opening: [
      '程实发现，今天的自己，是个女的。',
      '他对着铜镜看了足足十息——柳眉杏眼，钗环齐备，嗓音又软又甜。但天赋在，道具在，记忆在，连脸上那张看不见的嘴都在。',
      '"愚戏之唇，我这是？"',
      '"身份牌。"那张嘴见怪不怪，"这地方每天卯时抽签，抽到什么是什么。你今天是\'绸缎庄老板娘\'，恭喜。"',
      '"性别也换？"',
      '"性别算什么。"愚戏之唇咂咂嘴，"昨天这条街上的县太爷，今天在前门要饭。"',
      '程实对着镜子理了理鬓角，幽幽道："那我昨天是谁？"',
      '"谁知道呢。"',
      '窗外，整座城正在晨光里哗啦啦地"翻牌"——酒旗换了字号，衙门换了匾额，昨送孩子上学的娘，今天牵着别人的娃。'
    ],
