      '不是报时的钟。那口钟足有磨盘大，悬在城门楼上，黄铜钟身上铸着两个字：测谎。',
      '程实确实没事——所以他更想不通了。还是同行的旅人给他解的惑："客官是外乡人吧？测谎钟不听真假，听的是\'你信不信\'。你方才说\'我没事\'的时候，心里发虚了吧？"',
      '程实："……"',
      '他当然发虚。他进每一个试炼的时候，都发虚。',
      '完了。他看着那口钟，心里咯噔一下。',
      '这地方，克他。'
